package main

import (
	"fmt"
	"slices"
)

type Mutex map[[2]int]bool

func mutexPair(a, b int) [2]int {
	if a > b {
		a, b = b, a
	}
	return [2]int{a, b}
}
func (m Mutex) Has(a, b int) bool { return a != b && m[mutexPair(a, b)] }
func (m Mutex) Compatible(facts State) bool {
	numbers := facts.Numbers()
	for i, a := range numbers {
		for _, b := range numbers[i+1:] {
			if m.Has(a, b) {
				return false
			}
		}
	}
	return true
}

type GraphElement struct {
	Action, Fact  int
	Pre, Add, Del State
}
type GraphMemo struct {
	Level int
	Goals State
}
type GraphPlanResult struct {
	Status                    string
	Plan                      []int
	Layers                    [][]int
	Searched, MemoHits, Tried int
	Logs                      []string
	ComplementCount           int
}
type PlanningGraph struct {
	Actions      []GraphElement
	Goal         State
	FactLevels   []State
	FactMutex    []Mutex
	ActionLevels [][]GraphElement
	ActionMutex  []Mutex
	Memo         map[GraphMemo]bool
	Result       *GraphPlanResult
}

func (g *PlanningGraph) Extract(level int, goals State) ([][]int, bool) {
	if level == 0 {
		return [][]int{}, true
	}
	key := GraphMemo{level, goals}
	if g.Memo[key] {
		g.Result.MemoHits++
		return nil, false
	}
	g.Result.Searched++
	numbers := goals.Numbers()
	elements := g.ActionLevels[level-1]
	mutex := g.ActionMutex[level-1]
	var assign func(int, []int) ([][]int, bool)
	assign = func(at int, chosen []int) ([][]int, bool) {
		covered := State{}
		for _, i := range chosen {
			covered = covered.Union(elements[i].Add)
		}
		for at < len(numbers) && covered.Has(numbers[at]) {
			at++
		}
		if at == len(numbers) {
			pre := State{}
			for _, i := range chosen {
				pre = pre.Union(elements[i].Pre)
			}
			layers, ok := g.Extract(level-1, pre)
			if !ok {
				return nil, false
			}
			actions := []int{}
			for _, i := range chosen {
				if elements[i].Action >= 0 {
					actions = append(actions, elements[i].Action)
				}
			}
			slices.Sort(actions)
			return append(layers, actions), true
		}
		fact := numbers[at]
		achievers := []int{}
		for i, e := range elements {
			if e.Action < 0 && e.Fact == fact {
				achievers = append(achievers, i)
			}
		}
		for i, e := range elements {
			if e.Action >= 0 && e.Add.Has(fact) {
				achievers = append(achievers, i)
			}
		}
		for _, i := range achievers {
			compatible := true
			for _, j := range chosen {
				if mutex.Has(i, j) {
					compatible = false
					break
				}
			}
			if !compatible {
				continue
			}
			g.Result.Tried++
			next := append(slices.Clone(chosen), i)
			if layers, ok := assign(at+1, next); ok {
				return layers, true
			}
		}
		return nil, false
	}
	layers, ok := assign(0, nil)
	if !ok {
		g.Memo[key] = true
	}
	return layers, ok
}
func (g *PlanningGraph) Expand() {
	facts := g.FactLevels[len(g.FactLevels)-1]
	previousMutex := g.FactMutex[len(g.FactMutex)-1]
	elements := []GraphElement{}
	realActions := 0
	for _, a := range g.Actions {
		if facts.Contains(a.Pre) && previousMutex.Compatible(a.Pre) {
			elements = append(elements, a)
			realActions++
		}
	}
	for _, p := range facts.Numbers() {
		set := state([]int{p})
		elements = append(elements, GraphElement{Action: -1, Fact: p, Pre: set, Add: set})
	}
	mutex := Mutex{}
	for i, a := range elements {
		for j := i + 1; j < len(elements); j++ {
			b := elements[j]
			exclusive := a.Del.Intersects(b.Pre.Union(b.Add)) || b.Del.Intersects(a.Pre.Union(a.Add))
			if !exclusive {
				for _, p := range a.Pre.Numbers() {
					for _, q := range b.Pre.Numbers() {
						if previousMutex.Has(p, q) {
							exclusive = true
							break
						}
					}
					if exclusive {
						break
					}
				}
			}
			if exclusive {
				mutex[mutexPair(i, j)] = true
			}
		}
	}
	level := len(g.ActionLevels)
	g.Result.Logs = append(g.Result.Logs, fmt.Sprintf("action level %d: actions=%d noops=%d mutexes=%d", level, realActions, len(facts.Numbers()), len(mutex)))
	next := State{}
	achievers := map[int][]int{}
	for i, e := range elements {
		next = next.Union(e.Add)
		for _, p := range e.Add.Numbers() {
			achievers[p] = append(achievers[p], i)
		}
	}
	factMutex := Mutex{}
	numbers := next.Numbers()
	for i, p := range numbers {
		for _, q := range numbers[i+1:] {
			exclusive := true
			for _, x := range achievers[p] {
				for _, y := range achievers[q] {
					if x == y || !mutex.Has(x, y) {
						exclusive = false
						break
					}
				}
				if !exclusive {
					break
				}
			}
			if exclusive {
				factMutex[mutexPair(p, q)] = true
			}
		}
	}
	g.ActionLevels = append(g.ActionLevels, elements)
	g.ActionMutex = append(g.ActionMutex, mutex)
	g.FactLevels = append(g.FactLevels, next)
	g.FactMutex = append(g.FactMutex, factMutex)
}
func graphPlan(actions []GraphElement, initial, goal State, complementCount, limit int) *GraphPlanResult {
	r := &GraphPlanResult{ComplementCount: complementCount}
	g := &PlanningGraph{Actions: actions, Goal: goal, FactLevels: []State{initial}, FactMutex: []Mutex{{}}, Memo: map[GraphMemo]bool{}, Result: r}
	for level := 0; ; level++ {
		facts, mutex := g.FactLevels[level], g.FactMutex[level]
		r.Logs = append(r.Logs, fmt.Sprintf("fact level %d: facts=%d mutexes=%d", level, len(facts.Numbers()), len(mutex)))
		attempted := facts.Contains(goal) && mutex.Compatible(goal)
		if attempted {
			searched, hits := r.Searched, r.MemoHits
			layers, ok := g.Extract(level, goal)
			status := "fail"
			if ok {
				status = "success"
			}
			r.Logs = append(r.Logs, fmt.Sprintf("extract level %d: %s searched=%d memo_hits=%d", level, status, r.Searched-searched, r.MemoHits-hits))
			if ok {
				r.Status = "solved"
				r.Layers = layers
				for _, layer := range layers {
					r.Plan = append(r.Plan, layer...)
				}
				return r
			}
		} else if level >= 1 && len(facts.Numbers()) == len(g.FactLevels[level-1].Numbers()) && len(mutex) == len(g.FactMutex[level-1]) {
			r.Status = "unreachable"
			return r
		}
		if level == limit {
			r.Status = "level limit"
			return r
		}
		g.Expand()
	}
}

package main

import (
	"slices"
	"sort"
)

type State [4]uint64

func (s State) Has(p int) bool { return s[p/64]&(uint64(1)<<uint(p%64)) != 0 }
func (s *State) Put(p int)     { s[p/64] |= uint64(1) << uint(p%64) }
func (s State) Union(t State) State {
	for i := range s {
		s[i] |= t[i]
	}
	return s
}
func (s State) Without(t State) State {
	for i := range s {
		s[i] &^= t[i]
	}
	return s
}
func (s State) Contains(t State) bool {
	for i := range s {
		if s[i]&t[i] != t[i] {
			return false
		}
	}
	return true
}
func (s State) Intersects(t State) bool {
	for i := range s {
		if s[i]&t[i] != 0 {
			return true
		}
	}
	return false
}
func (s State) Numbers() []int {
	out := []int{}
	for i := 0; i < 256; i++ {
		if s.Has(i) {
			out = append(out, i)
		}
	}
	return out
}
func state(numbers []int) State {
	out := State{}
	for _, p := range numbers {
		out.Put(p)
	}
	return out
}
func (d *Domain) Subtype(t, u string) bool {
	for {
		if t == u {
			return true
		}
		if t == "object" {
			return false
		}
		t = d.Parents[t]
	}
}
func (d *Domain) Classify() {
	d.Fluent = map[string]bool{}
	for _, s := range d.Actions {
		for _, e := range s.Effects {
			d.Fluent[e.Atom.Predicate] = true
		}
	}
}
func substitute(a Atom, assignment map[string]string) Atom {
	out := Atom{Predicate: a.Predicate, Terms: make([]string, len(a.Terms))}
	for i, t := range a.Terms {
		out.Terms[i] = assignment[t]
	}
	return out
}

type GroundAction struct {
	Schema             *Schema
	Arguments          []string
	Cost, Number       int
	Pre, Neg, Add, Del State
}

func (a *GroundAction) Text() string { return Atom{a.Schema.Name, a.Arguments}.Text() }

type Candidate struct {
	Schema             *Schema
	Arguments          []string
	Pre, Neg, Add, Del map[string]Atom
	Reachable          bool
}
type SchemaCount struct{ Assignments, Candidates, Reachable int }
type GroundProblem struct {
	Domain                      *Domain
	Problem                     *Problem
	Facts                       []Atom
	FactIndex                   map[string]int
	Actions                     []*GroundAction
	Initial, Goal               State
	Unreachable                 []Atom
	Counts                      map[string]*SchemaCount
	CandidateCount, StaticFacts int
	Cache                       map[State]*Heuristic
}

func objectTypes(p *Problem) map[string]string {
	out := map[string]string{}
	for _, o := range p.Objects {
		out[o.Name] = o.Type
	}
	return out
}
func objectsOfType(d *Domain, p *Problem, t string) []string {
	out := []string{}
	for _, o := range p.Objects {
		if d.Subtype(o.Type, t) {
			out = append(out, o.Name)
		}
	}
	return out
}
func atomsContain(set map[string]Atom, required map[string]Atom) bool {
	for key := range required {
		if _, ok := set[key]; !ok {
			return false
		}
	}
	return true
}
func ground(d *Domain, p *Problem) *GroundProblem {
	g := &GroundProblem{Domain: d, Problem: p, FactIndex: map[string]int{}, Counts: map[string]*SchemaCount{}, Cache: map[State]*Heuristic{}}
	initial := map[string]Atom{}
	reachable := map[string]Atom{}
	for _, a := range p.Initial {
		initial[a.Text()] = a
		if d.Fluent[a.Predicate] {
			reachable[a.Text()] = a
		} else {
			g.StaticFacts++
		}
	}
	candidates := []*Candidate{}
	for _, s := range d.Actions {
		count := &SchemaCount{Assignments: 1}
		g.Counts[s.Name] = count
		choices := make([][]string, len(s.Parameters))
		for i, param := range s.Parameters {
			choices[i] = objectsOfType(d, p, param.Type)
			count.Assignments *= len(choices[i])
		}
		assignment := map[string]string{}
		arguments := make([]string, len(s.Parameters))
		var enumerate func(int)
		enumerate = func(at int) {
			if at < len(s.Parameters) {
				for _, object := range choices[at] {
					arguments[at] = object
					assignment[s.Parameters[at].Name] = object
					enumerate(at + 1)
				}
				return
			}
			c := &Candidate{Schema: s, Arguments: slices.Clone(arguments), Pre: map[string]Atom{}, Neg: map[string]Atom{}, Add: map[string]Atom{}, Del: map[string]Atom{}}
			for _, literal := range s.Conditions {
				a := substitute(literal.Atom, assignment)
				if a.Predicate == "=" || !d.Fluent[a.Predicate] {
					truth := false
					if a.Predicate == "=" {
						truth = a.Terms[0] == a.Terms[1]
					} else {
						_, truth = initial[a.Text()]
					}
					if truth == literal.Negative {
						return
					}
				} else if literal.Negative {
					c.Neg[a.Text()] = a
				} else {
					c.Pre[a.Text()] = a
				}
			}
			for _, literal := range s.Effects {
				a := substitute(literal.Atom, assignment)
				if literal.Negative {
					c.Del[a.Text()] = a
				} else {
					c.Add[a.Text()] = a
				}
			}
			for key := range c.Add {
				delete(c.Del, key)
			}
			candidates = append(candidates, c)
			count.Candidates++
		}
		enumerate(0)
	}
	g.CandidateCount = len(candidates)
	for {
		changed := false
		for _, c := range candidates {
			if !c.Reachable && atomsContain(reachable, c.Pre) {
				c.Reachable = true
				changed = true
				for key, a := range c.Add {
					reachable[key] = a
				}
			}
		}
		if !changed {
			break
		}
	}
	for _, a := range reachable {
		g.Facts = append(g.Facts, a)
	}
	objectNumbers := map[string]int{}
	for i, o := range p.Objects {
		objectNumbers[o.Name] = i
	}
	sort.Slice(g.Facts, func(i, j int) bool {
		a, b := g.Facts[i], g.Facts[j]
		if d.PredicateIndex[a.Predicate] != d.PredicateIndex[b.Predicate] {
			return d.PredicateIndex[a.Predicate] < d.PredicateIndex[b.Predicate]
		}
		aa, bb := make([]int, len(a.Terms)), make([]int, len(b.Terms))
		for k, t := range a.Terms {
			aa[k] = objectNumbers[t]
		}
		for k, t := range b.Terms {
			bb[k] = objectNumbers[t]
		}
		return slices.Compare(aa, bb) < 0
	})
	for i, a := range g.Facts {
		g.FactIndex[a.Text()] = i
	}
	toState := func(atoms map[string]Atom) State {
		out := State{}
		for key := range atoms {
			if number, ok := g.FactIndex[key]; ok {
				out.Put(number)
			}
		}
		return out
	}
	g.Initial = toState(initial)
	for _, c := range candidates {
		if !c.Reachable {
			continue
		}
		a := &GroundAction{Schema: c.Schema, Arguments: c.Arguments, Cost: c.Schema.Cost, Number: len(g.Actions), Pre: toState(c.Pre), Neg: toState(c.Neg), Add: toState(c.Add), Del: toState(c.Del)}
		g.Actions = append(g.Actions, a)
		g.Counts[c.Schema.Name].Reachable++
	}
	for _, a := range p.Goals {
		if number, ok := g.FactIndex[a.Text()]; ok {
			g.Goal.Put(number)
		} else if !d.Fluent[a.Predicate] {
			if _, trueStatic := initial[a.Text()]; !trueStatic {
				g.Unreachable = append(g.Unreachable, a)
			}
		} else {
			g.Unreachable = append(g.Unreachable, a)
		}
	}
	return g
}

package main

const infinity = 1 << 60

type Heuristic struct {
	Goalcount, Hmax, Hadd, FF, LMCount int
	Relaxed, Helpful                   []int
	Landmarks                          State
}

func (h *Heuristic) Value(name string) int {
	switch name {
	case "none":
		return 0
	case "goalcount":
		return h.Goalcount
	case "hmax":
		return h.Hmax
	case "hadd":
		return h.Hadd
	case "ff":
		return h.FF
	case "lmcount":
		return h.LMCount
	}
	panic("unknown heuristic")
}
func aggregate(costs []int, required State, sum bool) int {
	value := 0
	for _, p := range required.Numbers() {
		if costs[p] == infinity {
			return infinity
		}
		if sum {
			value += costs[p]
		} else {
			value = max(value, costs[p])
		}
	}
	return value
}
func relaxedCosts(g *GroundProblem, s State, sum bool) []int {
	costs := make([]int, len(g.Facts))
	for p := range costs {
		costs[p] = infinity
		if s.Has(p) {
			costs[p] = 0
		}
	}
	for {
		changed := false
		for _, a := range g.Actions {
			pre := aggregate(costs, a.Pre, sum)
			if pre == infinity {
				continue
			}
			value := a.Cost + pre
			for _, p := range a.Add.Numbers() {
				if value < costs[p] {
					costs[p] = value
					changed = true
				}
			}
		}
		if !changed {
			return costs
		}
	}
}
func reachableWithout(g *GroundProblem, s State, forbidden int) State {
	reachable := s
	for {
		previous := reachable
		for _, a := range g.Actions {
			if !a.Add.Has(forbidden) && reachable.Contains(a.Pre) {
				reachable = reachable.Union(a.Add)
			}
		}
		if reachable == previous {
			return reachable
		}
	}
}
func planningLevels(g *GroundProblem, s State) ([]int, []int) {
	facts, actions := make([]int, len(g.Facts)), make([]int, len(g.Actions))
	for p := range facts {
		facts[p] = infinity
		if s.Has(p) {
			facts[p] = 0
		}
	}
	for a := range actions {
		actions[a] = infinity
	}
	for level := 0; ; level++ {
		changed := false
		for i, a := range g.Actions {
			if actions[i] != infinity {
				continue
			}
			ready := true
			for _, p := range a.Pre.Numbers() {
				if facts[p] > level {
					ready = false
					break
				}
			}
			if !ready {
				continue
			}
			actions[i] = level
			for _, p := range a.Add.Numbers() {
				if facts[p] == infinity {
					facts[p] = level + 1
					changed = true
				}
			}
		}
		if !changed {
			return facts, actions
		}
	}
}
func (g *GroundProblem) Heuristics(s State) *Heuristic {
	if cached := g.Cache[s]; cached != nil {
		return cached
	}
	h := &Heuristic{}
	for _, p := range g.Goal.Numbers() {
		if !s.Has(p) {
			h.Goalcount++
		}
	}
	cmax, cadd := relaxedCosts(g, s, false), relaxedCosts(g, s, true)
	h.Hmax = aggregate(cmax, g.Goal, false)
	h.Hadd = aggregate(cadd, g.Goal, true)
	achievers := make([][]int, len(g.Facts))
	for i, a := range g.Actions {
		for _, p := range a.Add.Numbers() {
			achievers[p] = append(achievers[p], i)
		}
	}
	if h.Hadd == infinity {
		h.FF = infinity
	} else {
		best := make([]int, len(g.Facts))
		for p := range best {
			best[p] = -1
			if s.Has(p) || cadd[p] == infinity {
				continue
			}
			minimum := infinity
			for _, i := range achievers[p] {
				a := g.Actions[i]
				pre := aggregate(cadd, a.Pre, true)
				if pre != infinity && a.Cost+pre < minimum {
					minimum = a.Cost + pre
					best[p] = i
				}
			}
		}
		selected := make([]bool, len(g.Actions))
		var require func(int)
		require = func(p int) {
			if s.Has(p) {
				return
			}
			a := best[p]
			if selected[a] {
				return
			}
			selected[a] = true
			for _, q := range g.Actions[a].Pre.Numbers() {
				require(q)
			}
		}
		for _, p := range g.Goal.Numbers() {
			require(p)
		}
		for i, chosen := range selected {
			if chosen {
				h.Relaxed = append(h.Relaxed, i)
				h.FF += g.Actions[i].Cost
				if applicable(g.Actions[i], s) {
					h.Helpful = append(h.Helpful, i)
				}
			}
		}
	}
	factLevels, actionLevels := planningLevels(g, s)
	unreachable := false
	for _, p := range g.Goal.Numbers() {
		if factLevels[p] == infinity {
			unreachable = true
			break
		}
	}
	if unreachable {
		h.LMCount = infinity
	} else {
		h.Landmarks = g.Goal.Without(s)
		verified := map[int]bool{}
		verificationKnown := map[int]bool{}
		for {
			previous := h.Landmarks
			for _, p := range h.Landmarks.Numbers() {
				first := true
				common := State{}
				for _, i := range achievers[p] {
					if actionLevels[i] == factLevels[p]-1 {
						if first {
							common = g.Actions[i].Pre
							first = false
						} else {
							for k := range common {
								common[k] &= g.Actions[i].Pre[k]
							}
						}
					}
				}
				common = common.Without(s)
				for _, q := range common.Numbers() {
					if h.Landmarks.Has(q) {
						continue
					}
					if !verificationKnown[q] {
						verified[q] = !reachableWithout(g, s, q).Contains(g.Goal)
						verificationKnown[q] = true
					}
					if verified[q] {
						h.Landmarks.Put(q)
					}
				}
			}
			if h.Landmarks == previous {
				break
			}
		}
		h.LMCount = len(h.Landmarks.Numbers())
	}
	g.Cache[s] = h
	return h
}

package main

import (
	"fmt"
	"os"
	"slices"
	"strconv"
	"strings"
)

type Settings struct {
	Budget, Weight, LevelLimit int
	Runs                       []SearchSettings
	Repair                     SearchSettings
}
type Step struct {
	Name      string
	Arguments []string
}

func (s Step) Text() string { return Atom{s.Name, s.Arguments}.Text() }

type CandidatePlan struct {
	Problem, Label string
	Steps          []Step
}

func readSettings() Settings {
	s := Settings{}
	for _, line := range lines("input/params.txt") {
		if line == "" || line[0] == '#' {
			continue
		}
		a := strings.Split(line, " ")
		switch a[0] {
		case "budget":
			s.Budget = integer(a[1])
		case "weight":
			s.Weight = integer(a[1])
		case "graphplan":
			s.LevelLimit = integer(a[1])
		case "run":
			s.Runs = append(s.Runs, SearchSettings{a[1], a[2]})
		case "repair":
			s.Repair = SearchSettings{a[1], a[2]}
		}
	}
	return s
}
func readCandidates() []CandidatePlan {
	out := []CandidatePlan{}
	for _, line := range lines("input/candidates.txt") {
		if line == "" || line[0] == '#' {
			continue
		}
		if strings.HasPrefix(line, "plan ") {
			a := strings.Split(line, " ")
			out = append(out, CandidatePlan{Problem: a[1], Label: a[2]})
		} else if line != "end" {
			a := strings.Split(line[1:len(line)-1], " ")
			i := len(out) - 1
			out[i].Steps = append(out[i].Steps, Step{a[0], a[1:]})
		}
	}
	return out
}
func argumentCheck(d *Domain, args, expected []string, types map[string]string, noun string) string {
	if len(args) != len(expected) {
		return fmt.Sprintf("expected %d arguments, got %d", len(expected), len(args))
	}
	for i, a := range args {
		actual, ok := types[a]
		if !ok {
			return "unknown " + noun + " " + a
		}
		if !d.Subtype(actual, expected[i]) {
			return fmt.Sprintf("argument %d (%s) is not of type %s", i+1, a, expected[i])
		}
	}
	return ""
}
func validateDomain(d *Domain) {
	kept := []*Schema{}
	for _, s := range d.Actions {
		reason := ""
		types := map[string]string{}
		for _, p := range s.Parameters {
			types[p.Name] = p.Type
			if !slices.Contains(d.Types, p.Type) && reason == "" {
				reason = "unknown type " + p.Type
			}
		}
		if reason == "" {
			literals := append(slices.Clone(s.Conditions), s.Effects...)
			for _, l := range literals {
				a := l.Atom
				expected := []string{}
				if a.Predicate == "=" {
					expected = []string{"object", "object"}
				} else if i, ok := d.PredicateIndex[a.Predicate]; ok {
					expected = d.Predicates[i].Types
				} else {
					reason = a.Text() + ": unknown predicate " + a.Predicate
					break
				}
				if error := argumentCheck(d, a.Terms, expected, types, "variable"); error != "" {
					reason = a.Text() + ": " + error
					break
				}
			}
		}
		if reason != "" {
			d.Diagnostics = append(d.Diagnostics, "error: action "+s.Name+": "+reason)
		} else {
			kept = append(kept, s)
		}
	}
	d.Actions = kept
	used := map[string]bool{}
	for _, s := range d.Actions {
		for _, l := range append(slices.Clone(s.Conditions), s.Effects...) {
			used[l.Atom.Predicate] = true
		}
	}
	for _, p := range d.Predicates {
		if !used[p.Name] {
			d.Diagnostics = append(d.Diagnostics, "warning: predicate "+p.Name+" is not used by any action")
		}
	}
	d.Classify()
}
func validateProblem(d *Domain, p *Problem) {
	types := objectTypes(p)
	check := func(atoms []Atom, side string) []Atom {
		kept := []Atom{}
		seen := map[string]bool{}
		for _, a := range atoms {
			reason := ""
			if i, ok := d.PredicateIndex[a.Predicate]; !ok {
				reason = "unknown predicate " + a.Predicate
			} else {
				reason = argumentCheck(d, a.Terms, d.Predicates[i].Types, types, "object")
			}
			if reason == "" && seen[a.Text()] {
				reason = "duplicate"
			}
			if reason != "" {
				p.Diagnostics = append(p.Diagnostics, "warning: "+side+" "+a.Text()+": "+reason)
			} else {
				seen[a.Text()] = true
				kept = append(kept, a)
			}
		}
		return kept
	}
	p.Initial = check(p.Initial, "init")
	p.Goals = check(p.Goals, "goal")
}
func heading(text string, items []string) string {
	if len(items) == 0 {
		return text + " -"
	}
	return text + " " + strings.Join(items, " ")
}
func numberList(s State) string {
	numbers := s.Numbers()
	if len(numbers) == 0 {
		return "-"
	}
	return intList(numbers, ",")
}
func intList(numbers []int, separator string) string {
	out := make([]string, len(numbers))
	for i, n := range numbers {
		out[i] = strconv.Itoa(n)
	}
	return strings.Join(out, separator)
}
func domainLines(d *Domain) []string {
	out := []string{"== domain " + d.Name + " =="}
	out = append(out, d.Diagnostics...)
	for _, t := range d.Types {
		chain := []string{t}
		for t != "object" {
			t = d.Parents[t]
			chain = append(chain, t)
		}
		out = append(out, "type "+strings.Join(chain, " < "))
	}
	for _, p := range d.Predicates {
		kind := "static"
		if d.Fluent[p.Name] {
			kind = "fluent"
		}
		out = append(out, fmt.Sprintf("predicate %s/%d %s", p.Name, len(p.Types), kind))
	}
	for _, s := range d.Actions {
		add, del := 0, 0
		for _, e := range s.Effects {
			if e.Negative {
				del++
			} else {
				add++
			}
		}
		out = append(out, fmt.Sprintf("action %s/%d cost=%d pre=%d add=%d del=%d", s.Name, len(s.Parameters), s.Cost, len(s.Conditions), add, del))
	}
	return out
}
func groundingLines(g *GroundProblem) []string {
	d, p := g.Domain, g.Problem
	out := []string{"== problem " + p.Name + " =="}
	out = append(out, p.Diagnostics...)
	out = append(out, fmt.Sprintf("objects: %d", len(p.Objects)))
	for _, t := range d.Types {
		out = append(out, heading("  "+t+":", objectsOfType(d, p, t)))
	}
	out = append(out, fmt.Sprintf("static facts: %d", g.StaticFacts))
	for _, s := range d.Actions {
		c := g.Counts[s.Name]
		out = append(out, fmt.Sprintf("schema %s: assignments=%d candidates=%d reachable=%d", s.Name, c.Assignments, c.Candidates, c.Reachable))
	}
	out = append(out, fmt.Sprintf("candidates: %d reachable: %d", g.CandidateCount, len(g.Actions)), fmt.Sprintf("facts: %d init: %d goals: %d", len(g.Facts), len(g.Initial.Numbers()), len(g.Goal.Numbers())))
	for _, a := range g.Unreachable {
		out = append(out, "unreachable goal: "+a.Text())
	}
	counts := map[string]int{}
	for _, a := range g.Facts {
		counts[a.Predicate]++
	}
	items := []string{}
	for _, p := range d.Predicates {
		if d.Fluent[p.Name] {
			items = append(items, fmt.Sprintf("%s=%d", p.Name, counts[p.Name]))
		}
	}
	out = append(out, heading("facts by predicate:", items), "facts:")
	for i, a := range g.Facts {
		out = append(out, fmt.Sprintf("  %d %s", i, a.Text()))
	}
	out = append(out, "actions:")
	for i, a := range g.Actions {
		out = append(out, fmt.Sprintf("  %d %s cost=%d pre=%s neg=%s add=%s del=%s", i, a.Text(), a.Cost, numberList(a.Pre), numberList(a.Neg), numberList(a.Add), numberList(a.Del)))
	}
	return out
}

type Validation struct {
	Status   string
	Messages []string
	Correct  int
}

func (v Validation) Verdict() string {
	if v.Status == "valid" {
		return "valid " + v.Messages[0]
	}
	return v.Status + ": " + v.Messages[0]
}
func validateSteps(d *Domain, p *Problem, steps []Step) Validation {
	world := map[string]Atom{}
	for _, a := range p.Initial {
		world[a.Text()] = a
	}
	schemas := map[string]*Schema{}
	for _, s := range d.Actions {
		schemas[s.Name] = s
	}
	types := objectTypes(p)
	cost := 0
	for k, step := range steps {
		prefix := fmt.Sprintf("step %d %s: ", k+1, step.Text())
		schema := schemas[step.Name]
		if schema == nil {
			return Validation{"invalid", []string{prefix + "unknown action " + step.Name}, k}
		}
		expected := make([]string, len(schema.Parameters))
		for i, param := range schema.Parameters {
			expected[i] = param.Type
		}
		if reason := argumentCheck(d, step.Arguments, expected, types, "object"); reason != "" {
			return Validation{"invalid", []string{prefix + reason}, k}
		}
		assignment := map[string]string{}
		for i, param := range schema.Parameters {
			assignment[param.Name] = step.Arguments[i]
		}
		for _, condition := range schema.Conditions {
			a := substitute(condition.Atom, assignment)
			truth := false
			if a.Predicate == "=" {
				truth = a.Terms[0] == a.Terms[1]
			} else {
				_, truth = world[a.Text()]
			}
			if truth == condition.Negative {
				literal := Literal{a, condition.Negative}
				return Validation{"invalid", []string{prefix + "precondition " + literal.Text() + " is false"}, k}
			}
		}
		for _, e := range schema.Effects {
			if e.Negative {
				delete(world, substitute(e.Atom, assignment).Text())
			}
		}
		for _, e := range schema.Effects {
			if !e.Negative {
				a := substitute(e.Atom, assignment)
				world[a.Text()] = a
			}
		}
		cost += schema.Cost
	}
	messages := []string{}
	for _, a := range p.Goals {
		if _, ok := world[a.Text()]; !ok {
			messages = append(messages, "unsatisfied goal "+a.Text())
		}
	}
	if len(messages) > 0 {
		return Validation{"goal not reached", messages, len(steps)}
	}
	return Validation{"valid", []string{fmt.Sprintf("length=%d cost=%d", len(steps), cost)}, len(steps)}
}
func planSteps(g *GroundProblem, plan []int) []Step {
	out := make([]Step, len(plan))
	for i, a := range plan {
		out[i] = Step{g.Actions[a].Schema.Name, g.Actions[a].Arguments}
	}
	return out
}
func mapSteps(g *GroundProblem, steps []Step) []int {
	indices := map[string]int{}
	for i, a := range g.Actions {
		indices[a.Text()] = i
	}
	out := make([]int, len(steps))
	for i, s := range steps {
		out[i] = indices[s.Text()]
	}
	return out
}
func planCost(g *GroundProblem, plan []int) int {
	cost := 0
	for _, i := range plan {
		cost += g.Actions[i].Cost
	}
	return cost
}
func improve(g *GroundProblem, plan []int) []int {
	out := slices.Clone(plan)
	for at := 0; at < len(out); {
		s := g.Initial
		for _, i := range out[:at] {
			s = apply(g.Actions[i], s)
		}
		kept := slices.Clone(out[:at])
		for _, i := range out[at+1:] {
			if applicable(g.Actions[i], s) {
				s = apply(g.Actions[i], s)
				kept = append(kept, i)
			}
		}
		if goal(g, s) {
			out = kept
		} else {
			at++
		}
	}
	return out
}
func interfere(a, b *GroundAction) bool {
	return a.Del.Intersects(b.Pre.Union(b.Add)) || b.Del.Intersects(a.Pre.Union(a.Add)) || a.Add.Intersects(b.Neg) || b.Add.Intersects(a.Neg)
}
func parallelize(g *GroundProblem, plan []int) [][]int {
	layers := make([]int, len(plan))
	count := 0
	for j, index := range plan {
		a := g.Actions[index]
		layers[j] = 1
		for i, previous := range plan[:j] {
			b := g.Actions[previous]
			if b.Add.Intersects(a.Pre) || b.Del.Intersects(a.Neg) || interfere(a, b) {
				layers[j] = max(layers[j], layers[i]+1)
			}
		}
		count = max(count, layers[j])
	}
	out := make([][]int, count)
	for i, a := range plan {
		out[layers[i]-1] = append(out[layers[i]-1], a)
	}
	return out
}
func parallelValidation(g *GroundProblem, layers [][]int) string {
	s := g.Initial
	for k, layer := range layers {
		for i, index := range layer {
			a := g.Actions[index]
			if !applicable(a, s) {
				return fmt.Sprintf("invalid at layer %d", k+1)
			}
			for _, other := range layer[i+1:] {
				if interfere(a, g.Actions[other]) {
					return fmt.Sprintf("invalid at layer %d", k+1)
				}
			}
		}
		adds, deletes := State{}, State{}
		for _, index := range layer {
			a := g.Actions[index]
			adds = adds.Union(a.Add)
			deletes = deletes.Union(a.Del)
		}
		s = s.Without(deletes).Union(adds)
	}
	if goal(g, s) {
		return "valid"
	}
	return "goal not reached"
}

func transformedGraph(g *GroundProblem) ([]GraphElement, State, int) {
	negative := State{}
	for _, a := range g.Actions {
		negative = negative.Union(a.Neg)
	}
	complement := map[int]int{}
	for i, p := range negative.Numbers() {
		complement[p] = len(g.Facts) + i
	}
	initial := g.Initial
	for p, c := range complement {
		if !initial.Has(p) {
			initial.Put(c)
		}
	}
	actions := []GraphElement{}
	for i, a := range g.Actions {
		pre, add, del := a.Pre, a.Add, a.Del
		for _, p := range a.Neg.Numbers() {
			pre.Put(complement[p])
		}
		for _, p := range a.Del.Numbers() {
			if c, ok := complement[p]; ok {
				add.Put(c)
			}
		}
		for _, p := range a.Add.Numbers() {
			if c, ok := complement[p]; ok {
				del.Put(c)
			}
		}
		actions = append(actions, GraphElement{Action: i, Fact: -1, Pre: pre, Add: add, Del: del})
	}
	return actions, initial, len(complement)
}
func heuristicText(value int) string {
	if value == infinity {
		return "inf"
	}
	return strconv.Itoa(value)
}

var heuristicNames = []string{"goalcount", "hmax", "hadd", "ff", "lmcount"}

func heuristicValues(h *Heuristic) string {
	items := []string{}
	for _, name := range heuristicNames {
		items = append(items, name+"="+heuristicText(h.Value(name)))
	}
	return strings.Join(items, " ")
}
func actionTexts(g *GroundProblem, indices []int) []string {
	out := make([]string, len(indices))
	for i, a := range indices {
		out[i] = g.Actions[a].Text()
	}
	return out
}

type RunRecord struct {
	Settings SearchSettings
	Tag      string
	Result   *SearchResult
}
type ProblemResult struct {
	Ground  *GroundProblem
	Runs    []*RunRecord
	Graph   *GraphPlanResult
	Proof   *RunRecord
	Best    int
	Optimal string
	Solved  int
}
type Output struct {
	Plans, Graph, Validation, Comparison []string
	Validated, ValidPlans                int
}

func planBlock(g *GroundProblem, tag string, plan []int, seen map[string]string, output *Output) ([]string, []string) {
	line := fmt.Sprintf("plan: length=%d cost=%d", len(plan), planCost(g, plan))
	key := intList(plan, ",")
	if earlier, ok := seen[key]; ok {
		line += " (same as " + earlier + ")"
	} else {
		seen[key] = tag
	}
	out := []string{line}
	counts := map[string]int{}
	for k, index := range plan {
		a := g.Actions[index]
		counts[a.Schema.Name]++
		out = append(out, fmt.Sprintf("  %d %s", k+1, a.Text()))
	}
	items := []string{}
	for _, s := range g.Domain.Actions {
		if counts[s.Name] > 0 {
			items = append(items, fmt.Sprintf("%s=%d", s.Name, counts[s.Name]))
		}
	}
	out = append(out, heading("schemas:", items))
	layers := parallelize(g, plan)
	out = append(out, fmt.Sprintf("parallel: layers=%d", len(layers)))
	for k, layer := range layers {
		out = append(out, heading(fmt.Sprintf("  %d:", k+1), actionTexts(g, layer)))
	}
	improved := improve(g, plan)
	removed := len(plan) - len(improved)
	out = append(out, fmt.Sprintf("improved: length=%d cost=%d removed=%d", len(improved), planCost(g, improved), removed))
	if removed > 0 {
		for k, index := range improved {
			out = append(out, fmt.Sprintf("  %d %s", k+1, g.Actions[index].Text()))
		}
	}
	landmarks := g.Heuristics(g.Initial).Landmarks
	reached := State{}
	s := g.Initial
	for _, index := range plan {
		s = apply(g.Actions[index], s)
		for k := range reached {
			reached[k] |= s[k] & landmarks[k]
		}
	}
	out = append(out, fmt.Sprintf("landmarks reached: %d/%d", len(reached.Numbers()), len(landmarks.Numbers())))
	for _, p := range landmarks.Without(reached).Numbers() {
		out = append(out, "  missed "+g.Facts[p].Text())
	}
	originalValidation := validateSteps(g.Domain, g.Problem, planSteps(g, plan))
	improvedValidation := validateSteps(g.Domain, g.Problem, planSteps(g, improved))
	output.Validated++
	if originalValidation.Status == "valid" {
		output.ValidPlans++
	}
	validation := []string{tag + ": " + originalValidation.Verdict(), "  parallel: " + parallelValidation(g, layers), "  improved: " + improvedValidation.Verdict()}
	return out, validation
}
func profile(g *GroundProblem, proof *RunRecord) []string {
	plan := proof.Result.Plan
	out := []string{"-- profile (" + proof.Tag + ") --"}
	remaining := planCost(g, plan)
	s := g.Initial
	overestimates := make([]int, len(heuristicNames))
	for k := 0; k <= len(plan); k++ {
		h := g.Heuristics(s)
		out = append(out, fmt.Sprintf("  %d: h*=%d %s", k, remaining, heuristicValues(h)))
		for i, name := range heuristicNames {
			if h.Value(name) > remaining {
				overestimates[i]++
			}
		}
		if k < len(plan) {
			a := g.Actions[plan[k]]
			remaining -= a.Cost
			s = apply(a, s)
		}
	}
	counts := []string{}
	for i, name := range heuristicNames {
		counts = append(counts, fmt.Sprintf("%s=%d", name, overestimates[i]))
	}
	out = append(out, "overestimates: "+strings.Join(counts, " "), "-- causal links ("+proof.Tag+") --")
	supplier := make([]int, len(g.Facts))
	for k, index := range plan {
		a := g.Actions[index]
		items := []string{}
		for _, p := range a.Pre.Numbers() {
			items = append(items, fmt.Sprintf("%s<-%d", g.Facts[p].Text(), supplier[p]))
		}
		out = append(out, heading(fmt.Sprintf("  %d %s:", k+1, a.Text()), items))
		for _, p := range a.Add.Numbers() {
			supplier[p] = k + 1
		}
	}
	items := []string{}
	for _, p := range g.Goal.Numbers() {
		items = append(items, fmt.Sprintf("%s<-%d", g.Facts[p].Text(), supplier[p]))
	}
	return append(out, heading("  goal:", items))
}
func resultLine(r *SearchResult) string {
	if r.Status == "unreachable goal" {
		return "result: FAIL (unreachable goal)"
	}
	if r.Status == "solved" {
		return fmt.Sprintf("result: solved expanded=%d generated=%d", r.Expanded, r.Generated)
	}
	return fmt.Sprintf("result: FAIL (%s) expanded=%d generated=%d", r.Status, r.Expanded, r.Generated)
}
func processProblem(g *GroundProblem, settings Settings, out *Output) *ProblemResult {
	p := &ProblemResult{Ground: g, Best: -1, Optimal: "unknown"}
	out.Plans = append(out.Plans, "== problem "+g.Problem.Name+" ==")
	out.Graph = append(out.Graph, "== problem "+g.Problem.Name+" ==")
	out.Validation = append(out.Validation, "== problem "+g.Problem.Name+" ==")
	unreachable := len(g.Unreachable) > 0
	if unreachable {
		out.Plans = append(out.Plans, "initial h: unreachable goal")
	} else {
		h := g.Heuristics(g.Initial)
		out.Plans = append(out.Plans, "initial h: "+heuristicValues(h), fmt.Sprintf("landmarks: %d", len(h.Landmarks.Numbers())))
		for _, f := range h.Landmarks.Numbers() {
			out.Plans = append(out.Plans, "  "+g.Facts[f].Text())
		}
		out.Plans = append(out.Plans, fmt.Sprintf("relaxed plan: length=%d cost=%s", len(h.Relaxed), heuristicText(h.FF)))
		for _, a := range h.Relaxed {
			out.Plans = append(out.Plans, "  "+g.Actions[a].Text())
		}
		out.Plans = append(out.Plans, heading("helpful:", actionTexts(g, h.Helpful)))
	}
	for _, run := range settings.Runs {
		result := &SearchResult{Status: "unreachable goal"}
		if !unreachable {
			result = search(g, g.Initial, run, settings.Budget, settings.Weight)
		}
		record := &RunRecord{run, run.Tag(), result}
		p.Runs = append(p.Runs, record)
		if p.Proof == nil && result.Status == "solved" && (record.Tag == "ucs none" || record.Tag == "astar hmax") {
			p.Proof = record
		}
	}
	if unreachable {
		p.Graph = &GraphPlanResult{Status: "unreachable goal"}
		out.Graph = append(out.Graph, "result: FAIL (unreachable goal)")
	} else {
		actions, initial, count := transformedGraph(g)
		p.Graph = graphPlan(actions, initial, g.Goal, count, settings.LevelLimit)
		r := p.Graph
		out.Graph = append(out.Graph, fmt.Sprintf("complementary facts: %d", count))
		out.Graph = append(out.Graph, r.Logs...)
		if r.Status == "solved" {
			out.Graph = append(out.Graph, fmt.Sprintf("result: solved levels=%d length=%d cost=%d searched=%d memo_hits=%d tried=%d", len(r.Layers), len(r.Plan), planCost(g, r.Plan), r.Searched, r.MemoHits, r.Tried))
			for k, layer := range r.Layers {
				out.Graph = append(out.Graph, heading(fmt.Sprintf("layer %d:", k+1), actionTexts(g, layer)))
			}
		} else {
			out.Graph = append(out.Graph, fmt.Sprintf("result: FAIL (%s) searched=%d memo_hits=%d tried=%d", r.Status, r.Searched, r.MemoHits, r.Tried))
		}
	}
	gp := p.Graph
	p.Runs = append(p.Runs, &RunRecord{Settings: SearchSettings{"graphplan", "none"}, Tag: "graphplan", Result: &SearchResult{Status: gp.Status, Plan: gp.Plan, Expanded: gp.Searched, Generated: gp.Tried}})
	seen := map[string]string{}
	for _, record := range p.Runs {
		r := record.Result
		out.Plans = append(out.Plans, "-- "+record.Tag+" --", resultLine(r))
		length, cost := "-", "-"
		if r.Status == "solved" {
			p.Solved++
			value := planCost(g, r.Plan)
			if p.Best < 0 || value < p.Best {
				p.Best = value
			}
			length, cost = strconv.Itoa(len(r.Plan)), strconv.Itoa(value)
			block, validation := planBlock(g, record.Tag, r.Plan, seen, out)
			out.Plans = append(out.Plans, block...)
			out.Validation = append(out.Validation, validation...)
		}
		out.Comparison = append(out.Comparison, fmt.Sprintf("%s,%s,%s,%s,%s,%d,%d", g.Problem.Name, record.Settings.Algorithm, record.Settings.Heuristic, length, cost, r.Expanded, r.Generated))
	}
	if p.Proof != nil {
		p.Optimal = strconv.Itoa(planCost(g, p.Proof.Result.Plan))
		out.Plans = append(out.Plans, profile(g, p.Proof)...)
	} else {
		for _, record := range p.Runs {
			if slices.Contains([]string{"unreachable goal", "dead end", "exhausted", "unreachable"}, record.Result.Status) {
				p.Optimal = "none"
				break
			}
		}
	}
	out.Plans = append(out.Plans, "")
	out.Graph = append(out.Graph, "")
	out.Validation = append(out.Validation, "")
	return p
}
func bestText(value int) string {
	if value < 0 {
		return "-"
	}
	return strconv.Itoa(value)
}
func candidateLines(d *Domain, candidates []CandidatePlan, problems map[string]*ProblemResult, settings Settings) ([]string, int) {
	out := []string{"== candidates =="}
	validCount := 0
	for i, c := range candidates {
		p := problems[c.Problem]
		g := p.Ground
		v := validateSteps(d, g.Problem, c.Steps)
		base := fmt.Sprintf("candidate %d %s %s: ", i+1, c.Problem, c.Label)
		if v.Status == "valid" {
			validCount++
			plan := mapSteps(g, c.Steps)
			improved := improve(g, plan)
			out = append(out, base+v.Verdict(), fmt.Sprintf("  improved: length=%d cost=%d removed=%d best known=%s", len(improved), planCost(g, improved), len(c.Steps)-len(improved), bestText(p.Best)))
			continue
		}
		out = append(out, base+v.Status)
		for _, message := range v.Messages {
			out = append(out, "  "+message)
		}
		if len(g.Unreachable) > 0 {
			out = append(out, "  repair: FAIL (unreachable goal)")
			continue
		}
		prefix := mapSteps(g, c.Steps[:v.Correct])
		s := g.Initial
		for _, index := range prefix {
			s = apply(g.Actions[index], s)
		}
		repair := search(g, s, settings.Repair, settings.Budget, settings.Weight)
		if repair.Status != "solved" {
			out = append(out, "  repair: FAIL ("+repair.Status+")")
			continue
		}
		plan := append(slices.Clone(prefix), repair.Plan...)
		validation := validateSteps(d, g.Problem, planSteps(g, plan))
		out = append(out, fmt.Sprintf("  repair: kept=%d added=%d %s", len(prefix), len(repair.Plan), validation.Verdict()))
		for k, index := range plan {
			out = append(out, fmt.Sprintf("    %d %s", k+1, g.Actions[index].Text()))
		}
	}
	return out, validCount
}
func writeLines(name string, lines []string) {
	text := ""
	if len(lines) > 0 {
		text = strings.Join(lines, "\n") + "\n"
	}
	if e := os.WriteFile("output/"+name, []byte(text), 0644); e != nil {
		panic(e)
	}
}
func main() {
	d := readDomain()
	validateDomain(d)
	rawProblems := readProblems()
	settings := readSettings()
	candidates := readCandidates()
	grounding := domainLines(d)
	out := &Output{Comparison: []string{"problem,algorithm,heuristic,length,cost,expanded,generated"}}
	problems := []*ProblemResult{}
	byName := map[string]*ProblemResult{}
	for _, p := range rawProblems {
		validateProblem(d, p)
		g := ground(d, p)
		grounding = append(grounding, "")
		grounding = append(grounding, groundingLines(g)...)
		result := processProblem(g, settings, out)
		problems = append(problems, result)
		byName[p.Name] = result
	}
	out.Plans = append(out.Plans, "== summary ==")
	for _, p := range problems {
		out.Plans = append(out.Plans, fmt.Sprintf("%s: solved=%d/%d best=%s optimal=%s", p.Ground.Problem.Name, p.Solved, len(p.Runs), bestText(p.Best), p.Optimal))
	}
	for i, record := range problems[0].Runs {
		solved, best, expanded, generated := 0, 0, 0, 0
		for _, p := range problems {
			r := p.Runs[i].Result
			expanded += r.Expanded
			generated += r.Generated
			if r.Status == "solved" {
				solved++
				if planCost(p.Ground, r.Plan) == p.Best {
					best++
				}
			}
		}
		out.Plans = append(out.Plans, fmt.Sprintf("%s: solved=%d best=%d expanded=%d generated=%d", record.Tag, solved, best, expanded, generated))
	}
	candidateOutput, validCandidates := candidateLines(d, candidates, byName, settings)
	out.Validation = append(out.Validation, candidateOutput...)
	out.Validation = append(out.Validation, "", "== summary ==", fmt.Sprintf("plans: %d valid: %d", out.Validated, out.ValidPlans), fmt.Sprintf("candidates: %d valid: %d", len(candidates), validCandidates))
	if e := os.MkdirAll("output", 0755); e != nil {
		panic(e)
	}
	writeLines("grounding.txt", grounding)
	writeLines("plans.txt", out.Plans)
	writeLines("graphplan.txt", out.Graph)
	writeLines("validation.txt", out.Validation)
	writeLines("comparison.csv", out.Comparison)
}

package main

import (
	"os"
	"strconv"
	"strings"
)

type Expression struct {
	Word string
	List []Expression
}

func expressions(path string) []Expression {
	tokens := []string{}
	for _, line := range lines(path) {
		line = strings.SplitN(line, ";", 2)[0]
		line = strings.ReplaceAll(strings.ReplaceAll(line, "(", " ( "), ")", " ) ")
		tokens = append(tokens, strings.Fields(line)...)
	}
	at := 0
	var read func() Expression
	read = func() Expression {
		token := tokens[at]
		at++
		if token != "(" {
			return Expression{Word: token}
		}
		list := []Expression{}
		for tokens[at] != ")" {
			list = append(list, read())
		}
		at++
		return Expression{List: list}
	}
	out := []Expression{}
	for at < len(tokens) {
		out = append(out, read())
	}
	return out
}
func words(a []Expression) []string {
	out := make([]string, len(a))
	for i, e := range a {
		out[i] = e.Word
	}
	return out
}

type Typed struct{ Name, Type string }

func typedList(tokens []string) []Typed {
	out := []Typed{}
	pending := []string{}
	for i := 0; i < len(tokens); i++ {
		if tokens[i] == "-" {
			i++
			for _, name := range pending {
				out = append(out, Typed{name, tokens[i]})
			}
			pending = nil
		} else {
			pending = append(pending, tokens[i])
		}
	}
	for _, name := range pending {
		out = append(out, Typed{name, "object"})
	}
	return out
}

type Atom struct {
	Predicate string
	Terms     []string
}

func (a Atom) Text() string {
	if len(a.Terms) == 0 {
		return "(" + a.Predicate + ")"
	}
	return "(" + a.Predicate + " " + strings.Join(a.Terms, " ") + ")"
}
func parseAtom(e Expression) Atom { return Atom{e.List[0].Word, words(e.List[1:])} }

type Literal struct {
	Atom     Atom
	Negative bool
}

func (l Literal) Text() string {
	if l.Negative {
		return "(not " + l.Atom.Text() + ")"
	}
	return l.Atom.Text()
}
func literal(e Expression) Literal {
	if e.List[0].Word == "not" {
		return Literal{parseAtom(e.List[1]), true}
	}
	return Literal{Atom: parseAtom(e)}
}
func conjunction(e Expression) []Expression {
	if len(e.List) > 0 && e.List[0].Word == "and" {
		return e.List[1:]
	}
	return []Expression{e}
}

type Predicate struct {
	Name  string
	Types []string
}
type Schema struct {
	Name                string
	Parameters          []Typed
	Conditions, Effects []Literal
	Cost                int
}
type Domain struct {
	Name           string
	Types          []string
	Parents        map[string]string
	Predicates     []Predicate
	PredicateIndex map[string]int
	Actions        []*Schema
	Fluent         map[string]bool
	Diagnostics    []string
}
type Problem struct {
	Name           string
	Objects        []Typed
	Initial, Goals []Atom
	Diagnostics    []string
}

func readDomain() *Domain {
	e := expressions("input/domain.txt")[0]
	d := &Domain{Name: e.List[1].List[1].Word, Types: []string{"object"}, Parents: map[string]string{}, PredicateIndex: map[string]int{}, Fluent: map[string]bool{}}
	for _, section := range e.List[2:] {
		a := section.List
		switch a[0].Word {
		case ":types":
			tokens := words(a[1:])
			seen := map[string]bool{"object": true}
			for _, t := range tokens {
				if t != "-" && !seen[t] {
					seen[t] = true
					d.Types = append(d.Types, t)
					d.Parents[t] = "object"
				}
			}
			for _, t := range typedList(tokens) {
				d.Parents[t.Name] = t.Type
			}
		case ":predicates":
			for _, decl := range a[1:] {
				p := Predicate{Name: decl.List[0].Word}
				for _, t := range typedList(words(decl.List[1:])) {
					p.Types = append(p.Types, t.Type)
				}
				d.PredicateIndex[p.Name] = len(d.Predicates)
				d.Predicates = append(d.Predicates, p)
			}
		case ":action":
			s := &Schema{Name: a[1].Word, Cost: 1}
			for i := 2; i < len(a); i += 2 {
				switch a[i].Word {
				case ":parameters":
					s.Parameters = typedList(words(a[i+1].List))
				case ":precondition":
					for _, e := range conjunction(a[i+1]) {
						s.Conditions = append(s.Conditions, literal(e))
					}
				case ":effect":
					for _, e := range conjunction(a[i+1]) {
						if e.List[0].Word == "increase" {
							s.Cost = integer(e.List[2].Word)
						} else {
							s.Effects = append(s.Effects, literal(e))
						}
					}
				}
			}
			d.Actions = append(d.Actions, s)
		}
	}
	return d
}
func readProblems() []*Problem {
	out := []*Problem{}
	for _, e := range expressions("input/problems.txt") {
		p := &Problem{Name: e.List[1].List[1].Word}
		for _, section := range e.List[2:] {
			a := section.List
			switch a[0].Word {
			case ":objects":
				p.Objects = typedList(words(a[1:]))
			case ":init":
				for _, e := range a[1:] {
					p.Initial = append(p.Initial, parseAtom(e))
				}
			case ":goal":
				for _, e := range conjunction(a[1]) {
					p.Goals = append(p.Goals, parseAtom(e))
				}
			}
		}
		out = append(out, p)
	}
	return out
}
func integer(s string) int {
	v, e := strconv.Atoi(s)
	if e != nil {
		panic(e)
	}
	return v
}
func lines(path string) []string {
	b, e := os.ReadFile(path)
	if e != nil {
		panic(e)
	}
	if len(b) == 0 {
		return nil
	}
	return strings.Split(strings.TrimSuffix(string(b), "\n"), "\n")
}

package main

import (
	"container/heap"
	"slices"
)

func applicable(a *GroundAction, s State) bool { return s.Contains(a.Pre) && !s.Intersects(a.Neg) }
func apply(a *GroundAction, s State) State     { return s.Without(a.Del).Union(a.Add) }
func goal(g *GroundProblem, s State) bool      { return s.Contains(g.Goal) }

type SearchSettings struct{ Algorithm, Heuristic string }

func (s SearchSettings) Tag() string { return s.Algorithm + " " + s.Heuristic }

type SearchResult struct {
	Status              string
	Plan                []int
	Expanded, Generated int
}
type SearchNode struct {
	State              State
	G, D, H, F, Serial int
	Parent             *SearchNode
	Action             int
}
type SearchHeap []*SearchNode

func (h SearchHeap) Len() int { return len(h) }
func (h SearchHeap) Less(i, j int) bool {
	a, b := h[i], h[j]
	if a.F != b.F {
		return a.F < b.F
	}
	if a.H != b.H {
		return a.H < b.H
	}
	return a.Serial < b.Serial
}
func (h SearchHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *SearchHeap) Push(v any)   { *h = append(*h, v.(*SearchNode)) }
func (h *SearchHeap) Pop() any {
	a := *h
	v := a[len(a)-1]
	*h = a[:len(a)-1]
	return v
}
func bestFirst(g *GroundProblem, start State, settings SearchSettings, budget, weight int) *SearchResult {
	r := &SearchResult{}
	initialH := g.Heuristics(start).Value(settings.Heuristic)
	if initialH == infinity {
		r.Status = "dead end"
		return r
	}
	fValue := func(cost, depth, h int) int {
		switch settings.Algorithm {
		case "bfs":
			return depth
		case "ucs":
			return cost
		case "gbfs":
			return h
		case "astar":
			return cost + h
		case "wastar":
			return cost + weight*h
		}
		panic("unknown algorithm")
	}
	open := &SearchHeap{}
	serial := 0
	heap.Push(open, &SearchNode{State: start, H: initialH, F: fValue(0, 0, initialH), Action: -1})
	table := map[State]int{start: 0}
	costBased := settings.Algorithm == "ucs" || settings.Algorithm == "astar" || settings.Algorithm == "wastar"
	for open.Len() > 0 {
		node := heap.Pop(open).(*SearchNode)
		if costBased && node.G > table[node.State] {
			continue
		}
		if goal(g, node.State) {
			r.Status = "solved"
			for n := node; n.Parent != nil; n = n.Parent {
				r.Plan = append(r.Plan, n.Action)
			}
			slices.Reverse(r.Plan)
			return r
		}
		if r.Expanded == budget {
			r.Status = "budget"
			return r
		}
		r.Expanded++
		for i, a := range g.Actions {
			if !applicable(a, node.State) {
				continue
			}
			r.Generated++
			next := apply(a, node.State)
			cost := node.G + a.Cost
			previous, seen := table[next]
			if seen && (!costBased || previous <= cost) {
				continue
			}
			table[next] = cost
			h := g.Heuristics(next).Value(settings.Heuristic)
			if h == infinity {
				continue
			}
			serial++
			heap.Push(open, &SearchNode{State: next, G: cost, D: node.D + 1, H: h, F: fValue(cost, node.D+1, h), Serial: serial, Parent: node, Action: i})
		}
	}
	r.Status = "exhausted"
	return r
}

type LocalNode struct {
	State State
	Plan  []int
}

func enforcedHillClimbing(g *GroundProblem, start State, settings SearchSettings, budget int) *SearchResult {
	r := &SearchResult{}
	current := start
	hc := g.Heuristics(current).Value(settings.Heuristic)
	if hc == infinity {
		r.Status = "dead end"
		return r
	}
	for {
		if goal(g, current) {
			r.Status = "solved"
			return r
		}
		queue := []LocalNode{{State: current}}
		visited := map[State]bool{current: true}
		improved := false
		for head := 0; head < len(queue) && !improved; head++ {
			node := queue[head]
			if r.Expanded == budget {
				r.Status = "budget"
				return r
			}
			r.Expanded++
			for _, i := range g.Heuristics(node.State).Helpful {
				r.Generated++
				next := apply(g.Actions[i], node.State)
				if visited[next] {
					continue
				}
				visited[next] = true
				h := g.Heuristics(next).Value(settings.Heuristic)
				if h == infinity {
					continue
				}
				path := append(slices.Clone(node.Plan), i)
				if h < hc {
					r.Plan = append(r.Plan, path...)
					current = next
					hc = h
					improved = true
					break
				}
				queue = append(queue, LocalNode{next, path})
			}
		}
		if !improved {
			r.Status = "stuck"
			return r
		}
	}
}
func search(g *GroundProblem, start State, settings SearchSettings, budget, weight int) *SearchResult {
	if settings.Algorithm == "ehc" {
		return enforcedHillClimbing(g, start, settings, budget)
	}
	return bestFirst(g, start, settings, budget, weight)
}
